   "answer": 3,
   "explain": "】本题考查时事政治。2019 年5 月31 日，在北京召开的“不忘初心、牢记使命”主 题教育工作会议上，习近平总书记发表重要讲话时强调：开展“不忘初心、牢记使命” 主题教育，要牢牢把握守初心、担使命，找差距、抓落实的总要求，牢牢把握深入学 习贯彻新时代中国特色社会主义思想、锤炼忠诚干净担当的政治品格、团结带领全国 各族人民为实现伟大梦想共同奋斗的根本任务，努力实现理论学习有收获、思想政治 受洗礼、干事创业敢担当、为民服务解难题、清正廉洁作表率的具体目标，确保这次 主题教育取得扎扎实实的成效。习近平总书记在讲话中还指出，各地区各部门各单位 要结合实际，创造性开展工作，把学习教育、调查研究、检视问题、整改落实贯穿主 题教育全过程，努力取得最好成效。 故正确答案为D。",
