   "explain": "】本题考查法律常识。我国《宪法》第六十七条规定，全国人民代表大会常务委员 会行使下列职权：（十八）决定特赦。《宪法》第八十条规定，中华人民共和国主席根 据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，公布法律，任免 国务院总理、副总理、国务委员、各部部长、各委员会主任、审计长、秘书长，授予国 家的勋章和荣誉称号，发布特赦令，发布戒严令，宣布战争状态，发布动员令。所以， 特赦令由国家主席签发，全国人大常委会有权决定特赦。 故正确答案为B。",
