   "id": "xc-2020-gk-dishi-15",
   "module": "changshi",
   "q": "下列言论中涉及到的人才选拔制度，按出现顺序先后排列正确的是：①学通行修，经中博士②宗室非有军功论，不得为属籍2020年国家公务员录用考试《行测》真题（地市级网友回忆版）③九品访人，唯问中正④风吹金榜落凡世，三十三人名字香",
   "options": [
    "②①③④",
    "③②④①",
    "②④①③",
    "①③②④"
   ],
   "answer": 1,
   "explain": "】本题考查历史常识。①是我国汉代“四科取士”。根据《续汉书·百官志》记载的 汉光武帝诏书中指出，四科取士：一曰德行高妙，志节清白；二曰学通行修，经中博 士；三曰明达法令，足以决疑，能案章覆问，文中御史；四曰刚毅多略，遭事不惑，明 足以决，才任三辅令；②出自《史记·商君列传》，体现是战国时期商鞅在秦国实行 军功授爵的制度；③“九品”“中正”描述的是魏晋南北朝时期的九品中正制度；④ 出自唐代周匡物《及第谣》，意思是“因为皇恩浩荡，金榜题名，中举的人们的名字 都变香了。”描述的是科举制度。故本题中按照时间排序为②①③④。 故正确答案为B。",
