   "explain": "】本题考查地理常识。等高线弯曲部分向数值低处凸出——山脊；等高线弯曲部分 向数值高处凸出——山谷；等高线闭合，数值从中心向四周逐渐降低——山顶；数值 从中心向四周逐渐升高——盆地或洼地。题干中等高线地形图，等高线向数值高处凸 出，说明图中所示地形为山谷。C 项中“天寒日暮山谷里”，描述的就是山谷现象，与 图片相符。 故正确答案为C。",
