   "q": "扶贫干部某日需要走访村内6 个贫困户甲、乙、丙、丁、戊和己。已知甲和乙的走访次序要相邻，丙要在丁之前走访，戊要在丙之前走访，己只能在第一个或最后一个走访，问走访顺序有多少种不同的安排方式（ ）",
