   "module": "shuliang",
   "q": "一条圆形跑道长500 米，甲、乙两人从不同起点同时出发，均沿顺时针方向匀速跑步，已知甲跑了600 米后第一次追上乙，此后甲加速20%继续前进，又跑了1200 米后第二次追上乙，问甲出发后多少米第一次到达乙的出发点（ ）",
   "options": [
    "150",
    "180",
    "100",
    "120"
   ],
   "answer": 1,
   "explain": "】行程问题。由题意：甲又跑了1200 米后第二次追上乙，即第二次相遇，则甲比乙 多跑一圈，即多跑500 米，所以乙跑了：1200 −500＝700米，时间相同，路程与速度 成正比，即第一次相遇到第二次相遇期间，甲乙速度之比为12：7，由于甲第一次相遇 12 后提速20%，故甲乙原来速度之比为： 1+20%：7＝10：7，甲第一次相遇时跑了600 米， 600 时间为 10 ＝60 份，则乙的路程为：60 × 7＝420米，所以甲乙出发点相距：600 − 420＝180米，即甲出发后180 米第一次到达乙的出发点。 故正确答案为B。",
