   "module": "panduan",
   "q": "算术平均数描述了一组数据的平均趋势，是所有数据之和除以数据个数所得之商，在统计学中使用时应注意：出现极端数值、模糊不清的数据或者不同质的数据时，均不能计算算术平均数。根据上述定义，下列适于计算算术平均数的是（ ）",
   "options": [
    "某社区统计该社区居民的平均年龄，其中包括10 岁以下儿童204 人，90 岁以上老人26 人",
    "某公司统计35 岁以下青年职工的年平均收入，发现基本处于10—12 万元之间，其中有一人为公司高管，年收入百万元以上",
    "某学校统计本校青少年平均身高，将该校学前部、小学部和中学部全部学生计算在内全国服务电话：400-6353-606",
    "某市统计该市各区县留守儿童的平均数量，其中外出务工人员数量较多的区县无法进行准确统计，只提供了估算数据"
   ],
   "answer": 0,
   "explain": "】定义判断。关键词：出现极端数值、模糊不清的数据或者不同质的数据时，不能 使用算数平均数。 A 项，没有出现极端数值，模糊不清的数据和不同质数据，能够利用算数平均数，当 选； B 项，高管年收入百万元以上，而职工收入基本处于10—12 万元，高管收入为极端数 值，不适用算数平均数，排除； C 项，学前部不属于青少年，不适用计算算术平均数，排除； D 项，估算数据是模糊不清的数据，不适用计算算术平均数，排除。 故正确答案为A。",
   "year": 2020,
   "exam_type": "gk-dishi",
   "exam_volume": "行测",
