   "q": "客观—价值谬误是一种错误的推理，其前提是一个事实性的描述，而结论所表述的则是一个涉及价值意义的描述，而且这种推理没有预设明显的价值判断前提。根据上述定义，下列属于客观—价值谬误的是（ ）全国服务电话：400-6353-606",
