   "q": "社交裂变是一种利益驱动的商业模式，通过人与人之间的社交促进产品的传播与销售，本质上是通过利益驱动激励客户从而形成裂变。根据上述定义，下列不属于社交裂变的是（ ）",
   "options": [
    "某微信用户在购买到自己喜欢的商品后，经常拍照发在朋友圈中，慢慢地大家都知道她喜欢购买高档奢侈品",
    "某微商客户挑选好某个商品后，分享在自己的社交圈，好友帮助砍价后，客户可以低价购买，同时也宣传了该商品",
    "某电商平台的客户成功购买商品后，分享其链接，所有点击的人都能获得商家提供的随机金额的优惠券",
    "某咖啡店的老顾客参加“邀请好友免费喝咖啡”的活动后，可以获取一张套餐券全国服务电话：400-6353-606"
   ],
   "answer": 0,
   "explain": "】定义判断，选非题。关键词：通过人与人之间的社交；促进产品的传播与销售； 通过利益驱动激励客户从而形成裂变。 A 项，购买商品后拍照发到朋友圈，大家只是知道了她喜欢购买高档奢侈品，没有体 现促进产品的传播和销售，不符合定义，当选； B 项，好友帮助砍价后客户可以低价购买，同时宣传了商品，符合通过人与人之间的社 交促进产品的传播与销售，也符合利益驱动，符合定义，排除； C 项，分享链接所有点击的人可获得优惠券，符合通过人与人之间的社交促进产品的 传播与销售，也符合利益驱动，符合定义，排除； D 项，邀请好友免费喝咖啡，老顾客参加活动后可获得套餐券，符合通过人与人之间 的社交促进产品的传播与销售，也符合利益驱动，符合定义，排除。 故正确答案为A。",
   "year": 2020,
   "exam_type": "gk-dishi",
   "exam_volume": "行测",
   "topic": "",
   "src": "真题·PDF",
   "url": ""
