   "id": "xc-2020-gk-dishi-101",
   "module": "panduan",
   "q": "随着气温上升、热带雨林遭受闪电雷击并引发大火的几率也会上升，然而目前的监测表明，美洲热带雨林虽然更频繁地受到闪电雷击，却没有引发更多的森林大火。研究者认为这可能与近年来雨林中藤蔓植物大量增加有关。以下哪项如果为真，最能支持上述结论（ ）",
   "options": [
    "藤蔓茎干相对树枝电阻更小，能像建筑上的避雷针那样传导闪电，让大部分电流从自己的茎干传导",
    "闪电雷击常常引起温带森林大火，但热带雨林因为湿度较大，并不会产生较大火灾",
    "1968 年热带雨林中藤蔓植物的覆盖率是32%，当前其覆盖率已经高达60%，有的地区甚至超过75%",
    "雷击这样大规模、速度极快的放电，先摧毁了外部的藤蔓植物、中间的树木得到了保护"
   ],
   "answer": 0,
   "explain": "】加强论证。论点：热带雨林频繁地受到闪电雷击后没有引发更多的大火，原因与 藤蔓植物大量增加有关。 A 项，解释了藤蔓植物可以像避雷针那样传导闪电，从而避免发生火灾，解释说明，加 强论据，当选； B 项，指出热带雨林因湿度较大才未产生较大火灾，另有它因，可以削弱，排除； C 项，讨论的是藤蔓植物的覆盖率，与论点讨论的藤蔓植物与热带雨林大火的关系无 关，论题不一致，排除； D 项，摧毁了外部的藤蔓植物，中间的树木得到了保护，但摧毁的藤蔓植物是否引发 了火灾未提及，论据不可预见，排除； 故正确答案为A。",
