   "id": "xc-2020-gk-dishi-105",
   "module": "panduan",
   "q": "一般来说，动物的蛋会通过土壤中微生物和堆肥分解有机物时产生的热量来孵化，但这些微生物（包含细菌）也会穿透蛋壳、感染胚胎，自然情况下这一比例高于20%。然而，在澳洲有一种名为丛冢雉的鸟类，其蛋发生感染的几率仅为9%，研究者发现其蛋壳中含有溶酶酵素，研究者据此认为这种物质很可能就是抵御细菌侵扰的关键因素。以下哪项如果为真、没有削弱上述结论（ ）",
   "options": [
    "丛冢雉的蛋壳中所含的溶酶酵素量，与其他动物相比，含量大抵相当",
    "丛冢雉的蛋壳被一层纳米级的碳酸钙层包裹，拥有了更强的防水性和抗细菌入侵能力",
    "丛冢雉蛋散发一种特殊气味，会使附着在其蛋壳上的细菌数减少",
    "与其他动物的蛋壳相比，丛冢雉的蛋壳要薄三分之一，更易受到微生物的入侵根据所给材料，回答106—110 题某集团公司有生产、销售、研发、人事、财务、法务6 个部门，现有从前到后的6 栋办公楼：戊字楼、己字楼、庚字楼、辛字楼、壬字楼和癸字楼，每部门各一栋楼，并且各部门安排符合如下要求：（1）销售部在财务部和生产部之前；（2）人事部紧接在研发部或者生产部的后面；（3）紧接在法务部后面的是研发部或者销售部。全国服务电话：400-6353-606"
   ],
   "answer": 3,
   "explain": "】削弱论证，选非题。论点：溶酶酵素这种物质很可能就是抵御细菌侵扰的关键因 素。论据：在澳洲有一种名为丛冢雉的鸟类，其蛋发生感染的几率仅为9%。 A 项，指出丛冢雉蛋壳中含有溶酶酵素量和其他动物含量相当，说明溶酶酵素并非丛 冢雉蛋壳抵御细菌侵扰的关键因素，可以削弱，排除； B 项，指出碳酸钙层能够抵抗细菌侵入，有其它因素抵抗细菌侵扰，另有它因，可以削 弱，排除； C 项，指出散发的特殊气味会使细菌数减少，另有它因，可以削弱，排除； D 项，指出丛冢雉蛋壳更薄，更易受到微生物入侵，与论点讨论的溶酶酵素是否可以 抵御细菌侵扰无关，论题不一致，无法削弱，当选。 故正确答案为D。",
