   "id": "xc-2020-gk-fsheng-2",
   "module": "changshi",
   "q": "习近平总书记为我国生态文明建设倾注了巨大心血，足迹遍布大江南北、城市乡村，对各地的生态环境情况都了然于心、深思细究，对很多地域的生态环境寄予了期望。以下“期望”与地域对应正确的是（ ）",
   "options": [
    "要留住“飞泉泻万仞，舞鹤双低昂”那样的风景——贵州",
    "“长烟一空，皓月千里，浮光跃金，静影沉璧”这样的乡情美景不能弄没了——湖南",
    "要确保“一江清水向东流”——重庆",
    "要保护好“洞庭波涌连天雪，长岛人歌动地诗”——江西"
   ],
   "answer": 1,
   "explain": "】本题考查地理常识。 A 项，习近平在考察海南时引用了苏东坡的《和陶拟古九首》：飞泉泻万仞，舞鹤双低 昂。继而强调，保护海南生态环境不仅是海南自身发展的需要，也是我们国家的 需要，13 亿中国人应该有环境优美、适宜度假的地方，海南的同志在保护生态环 境方面责任重大，使命光荣。因此，是海南而非贵州； B 项，“长烟一空，皓月千里，浮光跃金，静影沉璧，渔歌互答，此乐何极”出自宋代 范仲淹的《岳阳楼记》。习近平总书记在湖南考察时谆谆告诫“长烟一空，皓月 千里，浮光跃金，静影沉璧”这样的乡情美景不能弄没了，要与现代生活融为一 体； C 项，2016 年8 月，习近平总书记在视察青海时，他叮嘱青海干部群众要保护好三江 源，保护好“中华水塔”，确保“一江清水向东流”。因此，是青海而非重庆； D 项，“洞庭波涌连天雪，长岛人歌动地诗”出自毛泽东的《答友人》，意为湖南社会 主义建设的形势有如洞庭湖的波涛汹",
