   "explain": "】本题考查时事政治。 A 项，杜富国，2018 年10 月11 日，在边境扫雷行动中面对复杂雷场中的不明爆炸物， 杜富国对战友喊出“你退后，让我来”，在进一步查明情况时突遇爆炸，英勇负 全国服务电话：400-6353-606 伤，失去双手和双眼，同组战友安然无恙。中央宣传部授予他“时代楷模”称号。 选项中描述的“践行社会主义核心价值观的优秀知识分子”是对黄大年的评价。 杜富国是“用生命担当使命的新时代英雄战士”； B 项，张富清，1924 年12 月出生，在解放大西北系列战斗中英勇善战、舍生忘死，荣 立西北野战军特等功一次、军一等功一次、师一等功一次、师二等功一次和团一 等功一次，并被授予军“战斗英雄”称号、师“战斗英雄”称号和“人民功臣” 奖章。中宣部授予张富清“时代楷模”称号。十三届全国人大常委会第十三次会 议表决通过的全国人大常委会关于授予国家勋章和国家荣誉称号的决定，张",
