   "explain": "】本题考查政治常识。图①反映的历史事件是中国共产党第一次全国代表大会的召 开。中国共产党第一次全国代表大会于1921 年7 月23 日至31 日在上海法租界和浙 江嘉兴南湖的红船上召开。图②历史事件是长征，时间是1934 年10 月至1936 年10 月。图③历史事件是古田会议，1929 年12 月28 日至29 日在福建古田召开了古田会 议。图④历史事件是中共七届二中全会，中共七届二中全会于1949 年3 月5 日至13 日在河北省平山县西柏坡举行。因此，正确排序为①③②④。 故正确答案为A。",
