   "id": "xc-2020-gk-fsheng-7",
   "module": "changshi",
   "q": "“套路贷”是假借民间借贷名义，非法占有被害人财物的违法犯罪行为，是扫黑除恶专项斗争的重点打击对象。下列关于“套路贷”的说法正确的是（ ）",
   "options": [
    "因“套路贷”属于非法行为，追债时一般不会采用仲裁、诉讼方式",
    "因法律规定民间借贷最高年利率为36%，故超过36%的可认定为“套路贷”",
    "“套路贷”犯罪案件可由犯罪行为发生地、结果发生地及犯罪嫌疑人居住地公安机关侦查",
    "我国刑法设置有专门针对“套路贷”的罪名"
   ],
   "answer": 2,
   "explain": "】本题考查法律常识。 A 项，根据最高人民法院、最高人民检察院、公安部、司法部《关于办理“套路贷”刑 事案件若干问题的意见》（以下简称《意见》）：套路贷是对以非法占有为目的， 假借民间借贷之名，诱使或迫使被害人签订“借贷”或变相“借贷”“抵 押”“担保”等相关协议，通过虚增借贷金额、恶意制造违约、肆意认定违约、 毁匿还款证据等方式形成虚假债权债务，并借助诉讼、仲裁、公证或者采用暴力、 威胁以及其他手段非法占有被害人财物的相关违法犯罪活动的概括性称谓，所以 A 项错误； B 项，根据《意见》：“套路贷”与平等主体之间基于意思自治而形成的民事借贷关系 存在本质区别，民间借贷的出借人是为了到期按照协议约定的内容收回本金并获 取利息，不具有非法占有他人财物的目的，也不会在签订、履行借贷协议过程中 实施虚增借贷金额、制造虚假给付痕迹、恶意制造违约、肆意认定违约、毁匿还 款证据等行为。因此，“套路贷”",
