   "answer": 0,
   "explain": "】本题考查时事政治。 A 项，“十三五”期间中国或建世界最大口径的光学红外望远镜。新一代大口径光学 红外望远镜设计总高31 米，镜面口径12 米。建成后，相当长一段时间将是世界 上口径最大的光学望远镜，为中国在暗能量本质、引力波源光学认证和研究、太 阳系外类地行星探测等重大前沿领域取得重大突破。但到2019 年尚未建成； B 项，2018 年1 月22 日晚，中国科学院云南天文台应用天文研究团组利用1.2m 望远 镜激光测距系统，在国内首次成功实现月球激光测距； C 项，南京大学天文与空间科学学院行星课题组与北京大学科维理天文研究所等单位 合作利用国家天文台的郭守敬望远镜发现了一类新的太阳系外行星族群—热海星。 相关研究论文于2018 年1 月9 日在《美国科学院院刊》（PNAS）发表，并被选为 当期杂志封面的研究亮点文章之一； D 项，2019 年7 月3 日，中日两国科学家同日发布一项",
