   "q": "下列关于电池的说法错误的是（ ）",
   "options": [
    "自行放电是蓄电池不可避免的渐生故障",
    "锂电池不会产生铅、汞等有害重金属物质",
    "干电池利用液态电解液产生电流",
    "太阳能电池产生的电是直流电"
   ],
   "answer": 2,
   "explain": "】本题考查化学常识。干电池是一种以糊状电解液来产生直流电的化学电池（湿电 池则为使用液态电解液的化学电池）。干电池是一次电池，是日常生活之中最为普遍、 轻便的电池，可以用于很多电器用品上。 故正确答案为C。",
   "year": 2020,
   "exam_type": "gk-fsheng",
