   "explain": "】本题考查科技常识。计算机通信的基本原理是将电信号转换为逻辑信号，其转换 方式是将高低电频表示为二进制数中的1 和0,再通过不同的二进制序列来表示所有的 信息。选项表述反了。 故正确答案为C。 第二部分 言语理解与表达",
