   "module": "shuliang",
   "q": "销售员小刘为客户准备了A、B、C 三个方案。已知客户接受方案A 的概率为40%。如果接受方案A，则接受方案B 的概率为60%，反之为30%，客户如果A 或B 方案都不接受，则接受C 方案的概率为90%，反之为10%。问将3 个方案按照客户接受概率从高到低排列，以下正确的是（ ）",
   "options": [
    "A>B>C",
    "A>C>B",
    "B>C>A",
    "C>B>A"
   ],
   "answer": 3,
   "explain": "】概率问题。由题意可知，接受方案A：概率为40%。接受A 且接受B 的概率为 方案：概率为24% + 18% = 42%。A、B 方案都不接受但接受C 方案的概率（1 −40%） × （1 −30%）× 90% = 37.8%，反之是A、B 方案至少接受一个且接受C 方案，概率 为（1 −42%）× 10% = 5.8%，则接受C 方案的概率为37.8% + 5.8% = 43.6%。三者 概率为C > B > A。 故正确答案为D。",
