   "explain": "】定义判断。关键词：出现极端数值、模糊不清的数据或者不同质的数据时，不能 使用算数平均数。 A 项，没有出现极端数值，模糊不清的数据和不同质数据，能够利用算数平均数，当 选； B 项，高管年收入百万元以上，而职工收入基本处于10—12 万元，高管收入为极端数 值，不适用算数平均数，排除； C 项，学前部不属于青少年，不适用计算算术平均数，排除； D 项，估算数据是模糊不清的数据，不适用计算算术平均数，排除。 故正确答案为A。",
