   "module": "panduan",
   "q": "编剧式观影者是指看影视剧不介意被剧透，甚至会提前查询剧情介绍、翻遍各种影评的人。这种观影者追求掌控剧情发展的感觉，不喜欢出乎意料。根据上述定义，下列属于编剧式观影者的是：",
